,p_process_name=>'CargaData'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :p3_codigo_productor is not null then',
'   begin',
'     select cp.capd_cacn_nu_cedula_rif,cp.capd_cacn_nu_cedula_rif,',
'            cc.cacn_primer_nombre, cc.cacn_segundo_nombre,',
'            cc.cacn_primer_apellido, cc.cacn_segundo_apellido',
'       into :p3_nacionalidad,:p3_cedula_rif, ',
'            :p3_primer_nombre,:p3_segundo_nombre,',
'            :p3_primer_apellido,:p3_segundo_apellido',
'       from cart_clientes cc, cart_productores cp',
'      where cc.cacn_nu_cedula_rif   = cp.capd_cacn_nu_cedula_rif',
'        and cc.cacn_cd_nacionalidad = cp.capd_cacn_cd_nacionalidad',
'        and cp.capd_cd_productor    = :p3_codigo_productor;',
'   exception',
'      when no_data_found then',
'           :p3_nacionalidad     := null;',
'           :p3_cedula_rif       := null; ',
'           :p3_primer_nombre    := null;',
'           :p3_segundo_nombre   := null;',
'           :p3_primer_apellido  := null;',
'           :p3_segundo_apellido := null;',
'   end;',
'end if;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
