 p_id=>wwv_flow_api.id(16655281873041796)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CargaData'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :p9_codusr is not null then',
'   begin',
'     select cp.capd_cacn_nu_cedula_rif,cp.capd_cacn_nu_cedula_rif,',
'            pi.primer_nombre, pi.segundo_nombre,',
'            pi.primer_apellido, pi.segundo_apellido,',
'            pi.email_primario,pi.email_secundario,cc.cacn_nm_apellido_razon,',
'            pi.fecha_nacimiento,',
'            pi.idintermediario,',
'            pi.sexo, pi.telefono_movil, pi.telefono_oficina,',
'            pi.dba_compania,pi.direccion_postal,pi.direccion_fisica',
'       into :p9_nacionalidad,:p9_cedula_rif, ',
'            :p9_primer_nombre,:p9_segundo_nombre,',
'            :p9_primer_apellido,:p9_segundo_apellido,',
'            :p9_email_primario,:p9_email_secundario,',
'            :p9_razon_social,',
'            :p9_fecha_nacimiento,',
'            :p9_idintermediario,',
'            :p9_sexo, :p9_telefono_movil, :p9_telefono_oficina,',
'            :p9_dba_compania, :p9_direccion_postal, :p9_direccion_fisica',
'       from cartera.cart_emails_cliente ce, cart_clientes cc, cart_productores cp, portal_intermediario pi',
'      where ce.cemc_cacn_nu_cedula_rif   = cc.cacn_nu_cedula_rif',
'        and ce.cemc_cacn_cd_nacionalidad = cc.cacn_cd_nacionalidad',
'        and cc.cacn_nu_cedula_rif        = cp.capd_cacn_nu_cedula_rif',
'        and cc.cacn_cd_nacionalidad      = cp.capd_cacn_cd_nacionalidad',
'        and cp.capd_cd_productor         = pi.codusr',
'        and pi.codusr                    = :p9_codusr;',
'   exception',
'      when no_data_found then',
'           :p9_nacionalidad     := null;',
'           :p9_cedula_rif       := null; ',
'           :p9_primer_nombre    := null;',
'           :p9_segundo_nombre   := null;',
'           :p9_primer_apellido  := null;',
'           :p9_segundo_apellido := null;',
'           :p9_email_primario   := null;',
'           :p9_razon_social     := null;',
'           :p9_fecha_nacimiento := null;',
'           :p9_idintermediario  := null;',
'           :p9_sexo             := null;',
'           :p9_telefono_movil   := null;',
'           :p9_telefono_oficina := null;',
'           :p9_dba_compania     := null;',
'           :p9_direccion_postal := null;',
'           :p9_direccion_fisica := null;',
'   end;',
'end if;',
'',
''))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
