wwv_flow_api.create_page_plug(
 p_id=>wwv_flow_api.id(16940485463328674)
,p_plug_name=>'Comisiones por Pagar'
,p_region_name=>'id_tabla_comisiones'
,p_parent_plug_id=>wwv_flow_api.id(16722030971117768)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_api.id(6544275179973229)
,p_plug_display_sequence=>30
,p_plug_display_point=>'BODY'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  cSql long;',
'begin',
' cSql :=  ''select cjfc_cd_sucursal, CJFC_CD_PRODUCTOR, CACN_NM_APELLIDO_RAZON ,CJFC_NU_POLIZA, CJFC_NU_FACTURA, ',
'                   ESTATUS_FACTURA ( cjfc_status_factura, ''''CAJA.CAJT_FACTURAS_EXTERNAS.CJFC_STATUS_FACTURA'''' ) StsFactura,',
'                   CJFC_NM_NOMBRE_RAZON , ',
'                   --CJFC_MT_TOTAL,  -- Solicitado 03/04/2024',
'                   prima (cjfc_cd_sucursal, CJFC_NU_FACTURA) Prima,',
'                   CONCAT(TO_CHAR(CAAC_PO_COMISION, ''''fm999G999D00''''), ''''%'''') PORC_COMISION,  ',
'                   CAAC_MT_COMISION, CAAC_CD_COMPANIA, max (CJOD_FE_OPERACION) ',
'              from cajt_operaciones_diarias_sng , cajt_facturas_externas, cart_account_current , cart_productores, cart_clientes , CAJT_COMPANIAS_EXTERNAS ',
'             where cjod_st_a <> ''''Z''''',
'               and CJOD_CJTO_CD_OPERACION IN (2013, 5004, 7979, 2081) ',
'               and CJOD_NU_RECIBO = CJFC_NU_FACTURA',
'               and CJFC_STATUS_FACTURA in (4,5) ',
'               and CJFC_NU_FACTURA = CAAC_NU_FACTURA',
'               and CAAC_TP_FACTURA = ''''E''''',
'               and CJOD_FE_OPERACION >= to_date(''''01/01/2023'''',''''MM/DD/YYYY'''')',
'               and CJFC_CD_PRODUCTOR = CAPD_CD_PRODUCTOR',
'               and CAPD_CACN_CD_NACIONALIDAD = CACN_CD_NACIONALIDAD',
'               and CAPD_CACN_NU_CEDULA_RIF = CACN_NU_CEDULA_RIF '';',
'            ',
' if :p10_razon_social is not null then',
'    cSql := cSql || '' and cjfc_nm_nombre_razon like ''''%''''||UPPER(:p10_razon_social)||''''%'''' '';',
' end if;',
' if :p10_nropoliza is not null then',
'    cSql := cSql || '' and cjfc_nu_poliza    = UPPER(:p10_nropoliza) '';',
' end if;',
'',
' cSql := cSql  || ''   and CJFC_CD_PRODUCTOR = :A_CODINTER      ',
'                      and not exists(select 1 ',
'                                        from cajt_movimientos_productores ',
'                                       where CJOD_NU_RECIBO = CJMP_NU_RECIBO',
'                                         and CJMP_FE_MOVIMIENTO >= to_date(''''01/01/2023'''',''''MM/DD/YYYY'''')) ',
'                    group by cjfc_cd_sucursal,CJFC_CD_PRODUCTOR, CACN_NM_APELLIDO_RAZON ,CJFC_NU_POLIZA, CJFC_NU_FACTURA, ',
'                             ESTATUS_FACTURA ( cjfc_status_factura, ''''CAJA.CAJT_FACTURAS_EXTERNAS.CJFC_STATUS_FACTURA'''' ),',
'                             CJFC_NM_NOMBRE_RAZON, CJFC_MT_TOTAL ,  ',
'                             CONCAT(TO_CHAR(CAAC_PO_COMISION, ''''fm999G999D00''''), ''''%''''),  CAAC_MT_COMISION , CAAC_CD_COMPANIA',
'                   union ',
'                   select fe.cjfc_cd_sucursal, fe.CJFC_CD_PRODUCTOR, cl.CACN_NM_APELLIDO_RAZON ,fe.CJFC_NU_POLIZA, fe.CJFC_NU_FACTURA, ',
'                           ESTATUS_FACTURA ( fe.cjfc_status_factura, ''''CAJA.CAJT_FACTURAS_EXTERNAS.CJFC_STATUS_FACTURA'''' ) StsFactura,',
'                           fe.CJFC_NM_NOMBRE_RAZON , ',
'                           -- fe.CJFC_MT_TOTAL,  ',
'                           prima (fe.cjfc_cd_sucursal, fe.CJFC_NU_FACTURA) Prima,',
'                           CONCAT(TO_CHAR(ac.CAAC_PO_COMISION, ''''fm999G999D00''''), ''''%'''') PORC_COMISION,  ',
'                           ac.CAAC_MT_COMISION, ac.CAAC_CD_COMPANIA, max (CJOD_FE_OPERACION) ',
'                     from  cajt_operaciones_diarias_sng od, ',
'                           cart_account_current ac,',
'                           cart_clientes cl, ',
'                           cart_productores it,',
'                           cajt_facturas_externas fe,',
'                           caja.prot_movimientos mp',
'                     where od.CJOD_CJTO_CD_OPERACION IN (2013, 5004, 7979, 2081) ',
'                       and od.CJOD_NU_RECIBO = fe.CJFC_NU_FACTURA',
'                       and fe.CJFC_STATUS_FACTURA in (4,5) ',
'                       and ac.CAAC_NU_FACTURA = fe.CJFC_NU_FACTURA ',
'                       and ac.CAAC_TP_FACTURA = ''''E''''',
'                       and od.CJOD_FE_OPERACION >= to_date(''''01/01/2023'''',''''MM/DD/YYYY'''')',
'                       and cl.CACN_CD_NACIONALIDAD = it.CAPD_CACN_CD_NACIONALIDAD  ',
'                       and cl.CACN_NU_CEDULA_RIF   = it.CAPD_CACN_NU_CEDULA_RIF    ',
'                       and it.CAPD_CD_PRODUCTOR    = fe.CJFC_CD_PRODUCTOR '';',
'                     ',
' if :p10_razon_social is not null then',
'    cSql := cSql || '' and cjfc_nm_nombre_razon like ''''%''''||UPPER(:p10_razon_social)||''''%'''' '';',
' end if;',
' if :p10_nropoliza is not null then',
'    cSql := cSql || '' and cjfc_nu_poliza = UPPER(:p10_nropoliza) '';',
' end if;',
'',
' cSql := cSql || '' and fe.cjfc_nu_factura           = mp.prmo_nu_recibo',
'                   and fe.CJFC_CD_PRODUCTOR         = mp.prmo_capd_cd_produc',
'                   and mp.prmo_capd_cd_produc       = :A_CODINTER',
'                group by fe.cjfc_cd_sucursal,fe.CJFC_CD_PRODUCTOR, cl.CACN_NM_APELLIDO_RAZON ,fe.CJFC_NU_POLIZA, fe.CJFC_NU_FACTURA, ',
'                         ESTATUS_FACTURA ( fe.cjfc_status_factura, ''''CAJA.CAJT_FACTURAS_EXTERNAS.CJFC_STATUS_FACTURA'''' ),',
'                         fe.CJFC_NM_NOMBRE_RAZON, fe.CJFC_MT_TOTAL ,  ',
'                         CONCAT(TO_CHAR(ac.CAAC_PO_COMISION, ''''fm999G999D00''''), ''''%''''),  ac.CAAC_MT_COMISION , ac.CAAC_CD_COMPANIA',
'                union',
'                select fe.cjfc_cd_sucursal,fe.CJFC_CD_PRODUCTOR, cl.CACN_NM_APELLIDO_RAZON ,fe.CJFC_NU_POLIZA, fe.CJFC_NU_FACTURA, ',
'                       ESTATUS_FACTURA ( fe.cjfc_status_factura, ''''CAJA.CAJT_FACTURAS_EXTERNAS.CJFC_STATUS_FACTURA'''' ) StsFactura,',
'                       fe.CJFC_NM_NOMBRE_RAZON , ',
'                       -- fe.CJFC_MT_TOTAL,  ',
'                       prima (fe.cjfc_cd_sucursal, fe.CJFC_NU_FACTURA) Prima,',
'                       CONCAT(TO_CHAR(ac.CAAC_PO_COMISION, ''''fm999G999D00''''), ''''%'''') PORC_COMISION,  ',
'                       ac.CAAC_MT_COMISION, ac.CAAC_CD_COMPANIA, max (CJOD_FE_OPERACION) ',
'                  from cajt_operaciones_diarias_sng od, ',
'                       cart_account_current ac,',
'                       cart_clientes cl, ',
'                       cart_productores it,',
'                       cajt_facturas_externas fe,',
'                       caja.prot_movimientos_otcia mp',
'                 where od.CJOD_CJTO_CD_OPERACION IN (2013, 5004, 7979, 2081) ',
'                   and od.CJOD_NU_RECIBO = fe.CJFC_NU_FACTURA',
'                   and fe.CJFC_STATUS_FACTURA in (4,5) ',
'                   and ac.CAAC_NU_FACTURA = fe.CJFC_NU_FACTURA ',
'                   and ac.CAAC_TP_FACTURA = ''''E''''',
'                   and od.CJOD_FE_OPERACION >= to_date(''''01/01/2023'''',''''MM/DD/YYYY'''')',
'                   and cl.CACN_CD_NACIONALIDAD = it.CAPD_CACN_CD_NACIONALIDAD  ',
'                   and cl.CACN_NU_CEDULA_RIF   = it.CAPD_CACN_NU_CEDULA_RIF    ',
'                   and it.CAPD_CD_PRODUCTOR    = fe.CJFC_CD_PRODUCTOR '';',
'                 ',
' if :p10_razon_social is not null then',
'    cSql := cSql || '' and cjfc_nm_nombre_razon like ''''%''''||UPPER(:p10_razon_social)||''''%'''' '';',
' end if;',
' if :p10_nropoliza is not null then',
'    cSql := cSql || '' and cjfc_nu_poliza = UPPER(:p10_nropoliza) '';',
' end if;',
'',
' cSql := cSql || '' and fe.cjfc_nu_factura           = mp.prmo_nu_recibo',
'                   and fe.CJFC_CD_PRODUCTOR         = mp.prmo_capd_cd_produc',
'                   and mp.prmo_capd_cd_produc       = :A_CODINTER',
'                group by fe.cjfc_cd_sucursal,fe.CJFC_CD_PRODUCTOR, cl.CACN_NM_APELLIDO_RAZON ,fe.CJFC_NU_POLIZA, fe.CJFC_NU_FACTURA, ',
'                         ESTATUS_FACTURA ( fe.cjfc_status_factura, ''''CAJA.CAJT_FACTURAS_EXTERNAS.CJFC_STATUS_FACTURA'''' ),',
'                         fe.CJFC_NM_NOMBRE_RAZON, fe.CJFC_MT_TOTAL ,  ',
'                         CONCAT(TO_CHAR(ac.CAAC_PO_COMISION, ''''fm999G999D00''''), ''''%''''),  ac.CAAC_MT_COMISION , ac.CAAC_CD_COMPANIA',
'                order by CJFC_CD_PRODUCTOR '';',
' return cSql;',
'end;'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P10_NROPOLIZA,P10_RAZON_SOCIAL'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
);
