,p_plug_template=>wwv_flow_api.id(6544275179973229)
,p_plug_display_sequence=>30
,p_plug_display_point=>'BODY'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'  select si.sisi_nu_siniestro, sp.sips_capc_cd_sucursal ||''-''||sp.sips_capc_carp_cd_ramo ||''-''||sp.sips_capc_capo_nu_poliza nropoliza ,',
'         cli.cacn_nm_apellido_razon, sp.sips_capc_capd_cd_productor,sisi_fe_ocurrencia,',
'         sisi_fe_declaracion,',
'         lv.rv_meaning, nvl(sum(sili_mt_pago),0), sum(mo.smcc_mt_movimiento) mtoPendiente,',
'         max(ri.smcc_mt_movimiento) ReservaInicial',
'    from SINT_MOVIMIENTOS_COBERTURAS_CE ri,SINT_MOVIMIENTOS_COBERTURAS_CE mo, SINT_liquidaciones li, cart_clientes cli,',
'         cg_ref_codes lv, SINT_PARTICIPACIONES_SINIESTRO sp, siniestros.sint_siniestros si',
'   where ri.smcc_sims_tp_movimiento = ''RI''',
'     and ri.smcc_sicc_cacb_cd_cobertura <> ''998''   -- excluye gastos',
'     and ri.smcc_sims_sisi_nu_siniestro = si.sisi_nu_siniestro',
'     and ri.smcc_sims_casu_cd_sucursal = si.sisi_casu_cd_sucursal',
'     and mo.smcc_sicc_cacb_cd_cobertura <> ''998''   -- excluye gastos',
'     and mo.smcc_sims_sisi_nu_siniestro = si.sisi_nu_siniestro',
'     and mo.smcc_sims_casu_cd_sucursal = si.sisi_casu_cd_sucursal',
'     and li.sili_cjte_cd_egreso(+)        = 700  --Indemnizacion',
'     and li.sili_sisi_nu_siniestro(+)     = si.sisi_nu_siniestro',
'     and li.sili_sisi_casu_cd_sucursal(+) = si.sisi_casu_cd_sucursal',
'     and cli.cacn_nm_apellido_razon = nvl(:p11_razon_social,cli.cacn_nm_apellido_razon)',
'     and cli.cacn_cd_nacionalidad = si.sisi_cacn_cd_nacionalidad',
'     and cli.cacn_nu_cedula_rif =   si.sisi_cacn_nu_cedula_rif',
'     and lv.rv_low_value = si.sisi_st_siniestro',
'     and lv.rv_domain = ''SINT_SINIESTROS.SISI_ST_SINIESTRO''',
'     and sp.sips_capc_cd_sucursal ||''-''||sp.sips_capc_carp_cd_ramo ||''-''||sp.sips_capc_capo_nu_poliza = nvl(:p11_nropoliza,sp.sips_capc_cd_sucursal ||''-''||sp.sips_capc_carp_cd_ramo ||''-''||sp.sips_capc_capo_nu_poliza)',
'     and sp.sips_capc_capd_cd_productor = :A_CODINTER     --1006',
'     and sp.sips_sice_cd_sucursal       = si.sisi_casu_cd_sucursal',
'     and sp.sips_sice_nu_siniestro      = si.sisi_nu_siniestro',
'     and si.sisi_st_siniestro in (''10'',''14'') ',
'     group by si.sisi_nu_siniestro, sp.sips_capc_cd_sucursal ||''-''||sp.sips_capc_carp_cd_ramo ||''-''||sp.sips_capc_capo_nu_poliza ,',
'         cli.cacn_nm_apellido_razon, sp.sips_capc_capd_cd_productor,sisi_fe_ocurrencia,',
'         sisi_fe_declaracion,',
'         lv.rv_meaning'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P11_NROPOLIZA,P11_RAZON_SOCIAL'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
);
