,p_plug_display_sequence=>30
,p_plug_display_point=>'BODY'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'  select si.sisi_casu_cd_sucursal,si.sisi_nu_siniestro, sp.sips_capc_cd_sucursal ||''-''||sp.sips_capc_carp_cd_ramo ||''-''||sp.sips_capc_capo_nu_poliza nropoliza ,',
'         cli.cacn_nm_apellido_razon, sp.sips_capc_capd_cd_productor,sisi_fe_ocurrencia,',
'         sisi_fe_declaracion,',
'         lv.rv_meaning, ',
'         RECLAMO_LEGAL (sp.sips_capc_cd_sucursal, si.sisi_nu_siniestro) Legal,',
'         nvl(PAGADO_RECLAMO (si.sisi_casu_cd_sucursal, si.sisi_nu_siniestro),0) MtoPagado, ',
'         --max(li.sili_fe_pago) FechaPago,',
'         nvl(PENDIENTE_RECLAMO (si.sisi_casu_cd_sucursal, si.sisi_nu_siniestro),0) MtoPendiente',
'    from cart_clientes cli, cg_ref_codes lv, SINT_PARTICIPACIONES_SINIESTRO sp, siniestros.sint_siniestros si',
'   where cli.cacn_nm_apellido_razon like nvl(''%''||UPPER(:p12_razon_social)||''%'',cli.cacn_nm_apellido_razon)',
'     and cli.cacn_cd_nacionalidad = si.sisi_cacn_cd_nacionalidad',
'     and cli.cacn_nu_cedula_rif =   si.sisi_cacn_nu_cedula_rif',
'     and lv.rv_low_value = si.sisi_st_siniestro',
'     and lv.rv_domain = ''SINT_SINIESTROS.SISI_ST_SINIESTRO''',
'     and sp.sips_capc_cd_sucursal ||''-''||sp.sips_capc_carp_cd_ramo ||''-''||sp.sips_capc_capo_nu_poliza = nvl(:p12_nropoliza,sp.sips_capc_cd_sucursal ||''-''||sp.sips_capc_carp_cd_ramo ||''-''||sp.sips_capc_capo_nu_poliza)',
'     and sp.sips_capc_capd_cd_productor = :A_CODINTER     --1006',
'     and sp.sips_sice_cd_sucursal       = si.sisi_casu_cd_sucursal',
'     and sp.sips_sice_nu_siniestro      = si.sisi_nu_siniestro',
'     group by si.sisi_casu_cd_sucursal,si.sisi_nu_siniestro, sp.sips_capc_cd_sucursal ||''-''||sp.sips_capc_carp_cd_ramo ||''-''||sp.sips_capc_capo_nu_poliza ,',
'         cli.cacn_nm_apellido_razon, sp.sips_capc_capd_cd_productor,sisi_fe_ocurrencia,',
'         sisi_fe_declaracion,',
'         lv.rv_meaning,',
'         RECLAMO_LEGAL (sp.sips_capc_cd_sucursal, si.sisi_nu_siniestro)'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P12_NROPOLIZA,P12_RAZON_SOCIAL'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
);
