,p_plug_name=>unistr('P\00F3lizas por Cobrar II')
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_api.id(6544275179973229)
,p_plug_display_sequence=>10
,p_plug_display_point=>'BODY'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  cSql varchar2(4000);',
'begin',
'  cSql := '' select cp.cacn_nm_apellido_razon NbreCia,',
'                   fa.cjfc_nm_nombre_razon RazonSocial,',
'                   fa.cjfc_nu_factura Factura, ',
'                   ESTATUS_FACTURA ( fa.cjfc_status_factura, ''''CAJA.CAJT_FACTURAS_EXTERNAS.CJFC_STATUS_FACTURA'''' ) StsFactura,',
'                   fa.cjfc_nu_poliza NroPoliza, ',
'                   pa.cjpc_fe_efectiva Fecha,',
'                   PRIMA_NETA (fa.CJFC_CD_SUCURSAL, fa.cjfc_nu_factura) Prima,',
'                   (PRIMA_NETA (fa.CJFC_CD_SUCURSAL, fa.cjfc_nu_factura) - fa.cjfc_abono) Pendiente,',
'                   rf.rv_meaning tpooperacion,fa.cjfc_financiadora FinanciadoraDiferido,',
'                   fa.cjfc_caac_cd_ramo_externo CodRamo,',
'                   ramo(fa.cjfc_caac_cd_ramo_externo) DescRamo',
'              from cart_clientes cp,',
'                   cajt_companias_externas co,',
'                   cart_clientes cl, cart_productores pr, caja.cajt_payment_facturas pa, cg_ref_codes rf, ',
'                   cajt_facturas_externas fa',
'             where cp.cacn_nu_cedula_rif   = co.cjce_cacn_nu_cedula_rif',
'               and cp.cacn_cd_nacionalidad = co.cjce_cacn_cd_nacionalidad',
'               and co.cjce_cd_compania     = pa.cjpc_cd_compania',
'               and cl.cacn_nu_cedula_rif   = pr.capd_cacn_nu_cedula_rif',
'               and cl.cacn_cd_nacionalidad = pr.capd_cacn_cd_nacionalidad',
'               and pr.capd_cd_productor    = fa.cjfc_cd_productor',
'               and pa.cjpc_cd_sucursal     = fa.cjfc_cd_sucursal',
'               and pa.cjpc_nu_factura      = fa.cjfc_nu_factura',
'               and pa.cjpc_nu_payment      = ( select MAX(de.cjpc_nu_payment)',
'                                                 from cajt_payment_facturas de',
'                                                where de.cjpc_cd_sucursal = fa.cjfc_cd_sucursal',
'                                                  and de.cjpc_nu_factura  = fa.cjfc_nu_factura )',
'               ',
'               and rf.rv_low_value      = fa.cjfc_tp_operacion',
'               and rf.rv_domain         = ''''CAJA_FACTURAS_EXTERNAS_TP_OPERACION''''',
'               and fa.cjfc_status_factura in (1,6) '';',
' if :p15_asegurado is not null then',
'    cSql := cSql || ',
'             '' and fa.cjfc_nm_nombre_razon like ''''%''''||UPPER(:p15_asegurado)||''''%'''' '';',
' end if;',
' ',
' if :p15_poliza is not null then',
'    cSql := cSql || ',
'             '' and fa.cjfc_nu_poliza = :p15_poliza '';',
' end if;',
' ',
' -- cSql := cSql || '' and (trunc(pa.cjpc_fe_efectiva) >= to_date(''''01/01/2023'''',''''MM/DD/YYYY'''') and trunc(pa.cjpc_fe_efectiva) <= sysdate) -- Se deshabilito el hasta 03/04/2024',
' ',
' cSql := cSql || '' and (trunc(pa.cjpc_fe_efectiva) >= to_date(''''01/01/2023'''',''''MM/DD/YYYY'''') ) ',
'                   and fa.cjfc_cd_productor = :A_CODINTER',
'                   order by pa.cjpc_fe_efectiva, fa.cjfc_nm_nombre_razon '';',
'                   ',
' return cSql;',
'',
'end;'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P15_POLIZA,P15_ASEGURADO'
