,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  v_fecha_efectiva DATE;',
'BEGIN',
'  IF NOT REGEXP_LIKE(:P18_FECHA_EFECTIVA, ''^\d{2}/\d{2}/\d{4}$'') THEN',
'     RETURN FALSE;',
'  END IF;',
'  BEGIN',
'    v_fecha_efectiva := TO_DATE(:P18_FECHA_EFECTIVA, ''MM/DD/YYYY'');',
'  EXCEPTION',
'    WHEN OTHERS THEN',
'         RETURN FALSE;',
'  END;',
'  RETURN TRUE;',
'END;'))
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>unistr('Error en Fecha Efectiva. Formato V\00E1lido: MM/DD/YYYY')
