wwv_flow_api.create_page_da_action(
 p_id=>wwv_flow_api.id(20073247911968522)
,p_event_id=>wwv_flow_api.id(20073140462968521)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
' cursor cur_datos is',
'   select distinct fa.cjfc_nm_nombre_razon razonsocial,',
'          to_char(fa.cjfc_fecha,''MM/DD/YYYY'') FechaEfectividad,',
'          to_char(pa.cjpc_fec_vencimiento,''MM/DD/YYYY'') FechaVencimiento  ',
'     from caja.cajt_payment_facturas pa, cajt_facturas_externas fa',
'    where trunc(pa.cjpc_fe_efectiva) >= to_date(''01/01/2023'',''MM/DD/YYYY'')',
'      and pa.cjpc_cd_sucursal     = fa.cjfc_cd_sucursal',
'      and pa.cjpc_nu_factura      = fa.cjfc_nu_factura',
'      and pa.cjpc_nu_payment      = ( select max(de.cjpc_nu_payment)',
'                                        from cajt_payment_facturas de',
'                                       where de.cjpc_cd_sucursal = fa.cjfc_cd_sucursal',
'                                         and de.cjpc_nu_factura  = fa.cjfc_nu_factura ) ',
'      and fa.cjfc_status_factura not in (3,7,8,9,10)',
'      and fa.cjfc_nu_poliza    = :p18_nropoliza',
'      and fa.cjfc_cd_productor = :APP_USER;',
'      --order by fa.cjfc_fecha desc;',
'begin',
' for c in cur_datos loop',
'     :p18_fecha_efectiva    := c.FechaEfectividad;',
'     :p18_fecha_vencimiento := c.FechaVencimiento;',
'     :p18_nombre            := c.razonsocial;',
'     :p18_apellido          := c.razonsocial;',
'     exit;',
'  end loop;',
'end;'))
,p_attribute_02=>'P18_NROPOLIZA'
,p_attribute_03=>'P18_FECHA_EFECTIVA,P18_FECHA_VENCIMIENTO,P18_NOMBRE,P18_APELLIDO'
,p_attribute_04=>'N'
,p_stop_execution_on_error=>'Y'
,p_wait_for_result=>'Y'
);
