 p_id=>wwv_flow_api.id(5868493631175489)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Guardar'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'       ',
'    IF :p19_Id_Accidente is null THEN',
'    ',
'        :P19_ID_ACCIDENTE := AMI_ACC_ACCIDENTE_SEQ.NEXTVAL;',
'        APEX_UTIL.SET_SESSION_STATE (''P19_ID_ACCIDENTE'', :P19_ID_ACCIDENTE);',
'        ',
'        INSERT INTO AMI_ACC_ACCIDENTE',
'            ( Id_Accidente, Fecha, Hora, Lugar, Carretera, Kilometro, Barrio, Municipio, NroVeh, ',
'              TipUsr, CodUsr, StsAccidente, FecRegistro )',
'          VALUES',
'            ( :p19_Id_Accidente, to_date(:p19_fecha_accidente,''MM/DD/YYYY''), :p19_Hora, :p19_Lugar, :p19_Carretera,',
'              :p19_Kilometros, :p19_Barrio, :p19_Municipio, :p19_Nro_Vehiculos,',
'              ''INT'', :A_CODINTER, ''VAL'', SYSDATE);',
'    ELSE',
'         UPDATE AMI_ACC_ACCIDENTE',
'            SET Fecha       = to_date(:p19_fecha_accidente,''MM/DD/YYYY''),',
'                Lugar       = :p19_Lugar,',
'                Hora        = :p19_Hora,',
'                Carretera   = :p19_Carretera,',
'                Kilometro   = :p19_Kilometros,',
'                Barrio      = :p19_Barrio,',
'                Municipio   = :p19_Municipio,',
'                NroVeh      = :p19_Nro_Vehiculos,',
'                FecRegistro = SYSDATE',
'          WHERE Id_Accidente = :p19_Id_Accidente;',
'    END IF;',
'    ',
'END;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(18155814972833903)
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(5868468927175488)
,p_process_sequence=>10
,p_process_point=>'BEFORE_BOX_BODY'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CargaDatos'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P19_ID_ACCIDENTE IS NOT NULL THEN',
'   BEGIN',
'      SELECT Fecha, Hora, Lugar, Carretera, Kilometro, Barrio, Municipio, NroVeh',
'        INTO :p19_Fecha_Accidente, :p19_Hora, :p19_Lugar, :p19_Carretera,',
'             :p19_Kilometros, :p19_Barrio, :p19_Municipio, :p19_Nro_Vehiculos',
'        FROM AMI_ACC_ACCIDENTE',
'       WHERE Id_Accidente = :p19_Id_Accidente;',
'   EXCEPTION',
'      WHEN NO_DATA_FOUND THEN',
'           :p19_Fecha_Accidente := NULL;',
'           :p19_Hora            := NULL;',
'           :p19_Lugar           := NULL;',
'           :p19_Carretera       := NULL;',
'           :p19_Kilometros      := NULL;',
'           :p19_Barrio          := NULL;',
'           :p19_Municipio       := NULL;',
'           :p19_Nro_Vehiculos   := NULL;',
'   END;',
'END IF;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
