,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
' nExiste NUMBER(1) := 0;',
'BEGIN',
'',
'  BEGIN',
'    SELECT 1',
'      INTO nExiste',
'      FROM AMI_ACC_POLICIA',
'     WHERE Id_Accidente = :P20_Id_Accidente;',
'  EXCEPTION ',
'     WHEN NO_DATA_FOUND THEN',
'          nExiste := 0;',
'  END;',
'  ',
'  IF nExiste = 0 THEN',
'     INSERT INTO AMI_ACC_POLICIA',
'        ( Id_Accidente, Nombre_Policia, Apellido_Policia, Placa_Policia, Cuartel_Policia,',
'          Numero_Querella, Escena_Policia, Actuacion_Policia)',
'     VALUES',
'        ( :P20_Id_Accidente, :P20_Nombre_Policia, :P20_Apellido_Policia, :P20_Nro_Placa, :P20_Cuartel,',
