'   BEGIN',
'      SELECT Nombre_Policia, Apellido_Policia, Placa_Policia, Cuartel_Policia,',
'             Numero_Querella, Escena_Policia',
'        INTO :P20_Nombre_Policia, :P20_Apellido_Policia, :P20_Nro_Placa, :P20_Cuartel,',
'             :P20_Nro_Querella, :P20_Policia_Escena',
'        FROM AMI_ACC_POLICIA',
'       WHERE Id_Accidente = :P20_Id_Accidente;',
'   EXCEPTION',
'       WHEN NO_DATA_FOUND THEN',
'            :P20_Nombre_Policia   := NULL;',
'            :P20_Apellido_Policia := NULL;',
'            :P20_Nro_Placa        := NULL;',
'            :P20_Nro_Querella     := NULL;',
'            :P20_Policia_Escena   := NULL;',
