wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(3901643914246491)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Cargar'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
' nExiste NUMBER(1) := 0;',
'BEGIN',
'',
'  BEGIN',
'     SELECT 1',
'       INTO nExiste',
'       FROM AMI_ACC_PROPIETARIO',
'      WHERE Nro_Vehiculo = 2',
'        AND Id_Accidente = :p22_id_accidente;',
'  EXCEPTION',
'     WHEN NO_DATA_FOUND THEN',
'          nExiste := 0;',
'  ',
'  END;',
'  ',
'  IF nExiste = 0 THEN',
'     INSERT INTO AMI_ACC_PROPIETARIO',
'       ( Id_Propietario, Id_Accidente, Nro_Vehiculo, Nombre, Apellido, Edad, Sexo, Email,',
'         Licencia, Estado_Emi_Licencia, Seguro_Social, Direccion, Pueblo, Codigo_Postal,',
'         Tlf_Residencia, Tlf_Trabajo, Cia_Seguros, Nro_Poliza )',
'     VALUES',
'       ( AMI_ACC_PROPIETARIO_SEQ.nextval, :p22_Id_Accidente, 2, :p22_Nbre_Dueno, :p22_Apellido_Dueno, :p22_Edad, :p22_Sexo, :p22_Email,',
'         :p22_No_Licencia, :p22_Estado_Licencia, :p22_Nro_Social, :p22_Direccion, :p22_Pueblo, :p22_Codigo_postal, :p22_Telefono_Residencia,',
'         :p22_Telefono_Trabajo, :p22_Cia_Seguros, :p22_Nro_Poliza );',
'         ',
'     IF :P22_CONDUCTOR_ES_EL_DUENO = ''SI'' THEN',
'        INSERT INTO AMI_ACC_CONDUCTOR',
'         ( Id_Conductor, Id_Accidente, Nro_Vehiculo, Nombre, Apellido, Edad, Sexo, Licencia, Estado_Emi_Licencia, Seguro_Social, ',
'           Direccion, Pueblo, Codigo_Postal, Tlf_Residencia, Tlf_Trabajo, Fecha_Marbete, Fecha_Venc_Marbete)',
'        VALUES',
'         ( AMI_ACC_CONDUCTOR_SEQ.nextval, :p22_Id_Accidente, 2,:p22_Nbre_Dueno, :p22_Apellido_Dueno, :p22_Edad, :p22_Sexo,',
'           :p22_No_Licencia, :p22_Estado_Licencia,:p22_Nro_Social, :p22_Direccion, :p22_Pueblo, :p22_Codigo_postal, ',
'           :p22_Telefono_Residencia, :p22_Telefono_Trabajo,to_date(:p22_Fecha_Marbete,''MM/DD/YYYY''), to_date(:p22_Fecha_Venc_Marbete,''MM/DD/YYYY'')  );',
'     ELSE',
'        INSERT INTO AMI_ACC_CONDUCTOR',
'         ( Id_Conductor, Id_Accidente, Nro_Vehiculo, Nombre, Apellido, Edad, Sexo, Licencia, Estado_Emi_Licencia, Seguro_Social, ',
'           Direccion, Pueblo, Codigo_Postal, Tlf_Residencia, Tlf_Trabajo, Fecha_Marbete, Fecha_Venc_Marbete)',
'        VALUES',
'         (  AMI_ACC_CONDUCTOR_SEQ.nextval, :p22_Id_Accidente, 2, :p22_Nbre_Conduc, :p22_Apellido_Conduc, :p22_Edad_Conduc, :p22_Sexo_Conduc,',
'           :p22_Nro_Licencia_Conduc, :p22_Edo_Lice_Conduc, :p22_Nro_Social_Conduc, :p22_Direc_Conduc, :p22_Pueblo_Conduc, :p22_Cod_Postal_Conduc,',
'           :p22_Tlf_Reside_Conductor, :p22_Tlf_Traba_Conductor, to_date(:p22_Fecha_Marbete,''MM/DD/YYYY''), to_date(:p22_Fecha_Venc_Marbete,''MM/DD/YYYY'') );',
'     END IF;',
'     ',
'     INSERT INTO AMI_ACC_VEHICULO',
'         ( Id_Vehiculo, Id_Accidente, Nro_Vehiculo, MarcaVeh, ModeloVeh, AnoVeh, ColorVeh,',
'           Tablilla, Millaje, NroVin, NroRegistro, Observa)',
'     VALUES',
'         ( AMI_ACC_VEHICULO_SEQ.nextval, :p22_Id_Accidente, 2, :p22_Marca_Veh, :p22_Modelo_Veh, :p22_Anual_Veh,',
'           :p22_Color_Veh, :p22_Tablilla_Veh, :p22_Millaje_Veh, :p22_Nro_Motor_Veh, :p22_Nro_Registro, :p22_Comentario',
'         );',
'     ',
'  ELSE',
'     UPDATE AMI_ACC_PROPIETARIO',
'        SET  Nombre              = :p22_Nbre_Dueno,',
'             Apellido            = :p22_Apellido_Dueno, ',
'             Edad                = :p22_Edad, ',
'             Sexo                = :p22_Sexo, ',
'             Email               = :p22_Email, ',
'             Licencia            = :p22_No_Licencia,',
'             Estado_Emi_Licencia = :p22_Estado_Licencia,',
'             Seguro_Social       = :p22_Nro_Social, ',
'             Direccion           = :p22_Direccion, ',
'             Pueblo              = :p22_Pueblo, ',
'             Codigo_Postal       = :p22_Codigo_postal,',
'             Tlf_Residencia      = :p22_Telefono_Residencia, ',
'             Tlf_Trabajo         = :p22_Telefono_Trabajo,',
'             Cia_Seguros         = :p22_Cia_Seguros, ',
'             Nro_Poliza          = :p22_Nro_Poliza',
'      WHERE Nro_Vehiculo = 2',
'        AND Id_Accidente = :p22_Id_Accidente;',
'      ',
'      IF :P22_CONDUCTOR_ES_EL_DUENO = ''SI'' THEN ',
'        UPDATE AMI_ACC_CONDUCTOR',
'           SET Nombre              = :p22_Nbre_Dueno,',
'               Apellido            = :p22_Apellido_Dueno, ',
'               Edad                = :p22_Edad, ',
'               Sexo                = :p22_Sexo,',
'               Licencia            = :p22_No_Licencia,',
'               Estado_Emi_Licencia = :p22_Estado_Licencia,',
'               Seguro_Social       = :p22_Nro_Social, ',
'               Direccion           = :p22_Direccion, ',
'               Pueblo              = :p22_Pueblo, ',
'               Codigo_Postal       = :p22_Codigo_Postal, ',
'               Tlf_Residencia      = :p22_Telefono_Residencia, ',
'               Tlf_Trabajo         = :p22_Telefono_Trabajo, ',
'               Fecha_Marbete       = to_date(:p22_Fecha_Marbete,''MM/DD/YYYY''), ',
'               Fecha_Venc_Marbete  = to_date(:p22_Fecha_Venc_Marbete,''MM/DD/YYYY'')',
'         WHERE Nro_Vehiculo = 2',
'           AND Id_Accidente = :p22_Id_Accidente;',
'      ELSE',
'        UPDATE AMI_ACC_CONDUCTOR',
'           SET Nombre              = :p22_Nbre_Conduc,',
'               Apellido            = :p22_Apellido_Conduc, ',
'               Edad                = :p22_Edad_Conduc, ',
'               Sexo                = :p22_Sexo_Conduc,',
'               Licencia            = :p22_Nro_Licencia_Conduc,',
'               Estado_Emi_Licencia = :p22_Edo_Lice_Conduc,',
'               Seguro_Social       = :p22_Nro_Social_Conduc, ',
'               Direccion           = :p22_Direc_Conduc, ',
'               Pueblo              = :p22_Pueblo_Conduc, ',
'               Codigo_Postal       = :p22_Cod_Postal_Conduc, ',
'               Tlf_Residencia      = :p22_Tlf_Reside_Conductor, ',
'               Tlf_Trabajo         = :p22_Tlf_Traba_Conductor, ',
'               Fecha_Marbete       = to_date(:p22_Fecha_Marbete,''MM/DD/YYYY''), ',
'               Fecha_Venc_Marbete  = to_date(:p22_Fecha_Venc_Marbete,''MM/DD/YYYY'')',
'         WHERE Nro_Vehiculo = 2',
'           AND Id_Accidente = :p22_Id_Accidente;',
'      END IF;',
'      ',
'      UPDATE AMI_ACC_VEHICULO',
'         SET MarcaVeh    = :p22_Marca_Veh, ',
'             ModeloVeh   = :p22_Modelo_Veh, ',
'             AnoVeh      = :p22_Anual_Veh, ',
'             ColorVeh    = :p22_Color_Veh,',
'             Tablilla    = :p22_Tablilla_Veh, ',
'             Millaje     = :p22_Millaje_Veh, ',
'             NroVin      = :p22_Nro_Motor_Veh, ',
'             NroRegistro = :p22_Nro_Registro, ',
'             Observa     = :p22_Comentario',
'       WHERE Nro_Vehiculo = 2',
'         AND Id_Accidente = :p22_Id_Accidente;',
'',
'  END IF;',
'',
'END;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
