 p_id=>wwv_flow_api.id(3902052778246495)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Guardar'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'cursor cur_emails is',
'   select rv_meaning',
'     from cg_ref_codes',
'    where rv_domain=''EMAIL_RECLAMOS''',
'    order by rv_low_value;',
'l_html_header  clob;',
' l_html_table_1 clob;',
' l_html_table_2 clob;',
' l_html_table_3 clob;',
' l_html_table_4 clob;',
' l_html_table_5 clob;',
' l_html_table_6 clob;',
' l_html_table_7 clob;',
' l_html_table_8 clob;',
' l_html_footer  clob;',
'BEGIN',
'  BEGIN',
'    UPDATE AMI_ACC_ACCIDENTE',
'       SET StsAccidente = ''SOL'',',
'           Confirma     = :p23_acepto',
'     WHERE Id_Accidente = :p23_Id_Accidente;',
'  END;',
'',
'  IF :p23_acepto = ''S'' THEN',
'           l_html_header := ''<html>',
'                        <head>',
'                        <body>',
'                        <style>',
'                                 .styled-table {',
'                                                text-align: left;',
'                                                border-collapse: collapse;',
'                                                margin: 25px 0;',
'                                                font-size: 0.9em;',
'                                                font-family: sans-serif;',
'                                                min-width: 400px;',
'                                                box-shadow: 0 0 20px rgba(0, 0, 0, 0.15);',
'                                              }',
'                                 .styled-table thead tr',
'                                              {',
'                                                background-color: #009879;',
'                                                color: #ffffff;',
'                                                text-align: left;',
'                                              }',
'                                 .styled-table th, styled-table td {',
'                                                   padding: 12px 15px;',
'                                                 }',
'                                 .styled-table tbody tr {',
'                                                        border-bottom: 1px solid #dddddd;',
'                                                       }',
'',
'                                 .styled-table tbody tr:nth-of-type(even) {',
'                                            background-color: #f3f3f3;',
'                                  }',
'',
'                                 .styled-table tbody tr:last-of-type {',
'                                    border-bottom: 2px solid #009879;',
'                                    }',
'',
'                                 .styled-table tbody tr.active-row {',
'                                    font-weight: bold;',
'                                    color: #009879;',
'                                    }',
'',
'                               </style> ',
'',
'                 <b>Hola, ''||:A_DISPLAYNAME||''</b>,<br>',
'                 <br>',
'                    Su solicitud se ha regisrado!<br>',
'                 <br>',
'                 <b>Detalle del Informe Amistoso</b><br>',
'                 <br>'';',
'            ',
'      pr_admin_intermediario.html_amistoso_amistoso      ( :p23_Id_Accidente, l_html_table_1 );',
'      pr_admin_intermediario.html_amistoso_datos_policia ( :p23_Id_Accidente, l_html_table_2 );',
'      pr_admin_intermediario.html_amistoso_propietario   ( :p23_Id_Accidente, 1, l_html_table_3 );',
'      pr_admin_intermediario.html_amistoso_conductor     ( :p23_Id_Accidente, 1, l_html_table_4 );',
'      pr_admin_intermediario.html_amistoso_vehiculo      ( :p23_Id_Accidente, 1, l_html_table_5 );',
