'BEGIN',
' IF :P31_ID_CATASTROFE IS NULL THEN',
' ',
'    :P31_ID_CATASTROFE := INCIDENTE_CATASTROFE_SEQ.NEXTVAL;',
'    APEX_UTIL.SET_SESSION_STATE (''P31_ID_CATASTROFE'', :P31_ID_CATASTROFE);',
'    ',
'    INSERT INTO INCIDENTE_CATASTROFE',
'      ( Id_Catastrofe, NbreAsegurado, NroPoliza, Email, TlfAsegurado,',
'        DirecPostal, DirecFisica, TipUsr, CodUsr, FecRegistro, StsCatastrofe )',
'    VALUES',
'      ( :p31_Id_Catastrofe, :p31_NbreAsegurado, :p31_Nro_Poliza, :p31_Email, :p31_TlfAsegurado,',
'        :p31_Direccion_Postal, :p31_Direccion_Fisica, ''INT'', :A_CODINTER, SYSDATE, ''VAL'' );',
' ELSE',
' ',
'    UPDATE INCIDENTE_CATASTROFE',
'       SET NbreAsegurado  = :p31_NbreAsegurado,',
'           NroPoliza      = :p31_Nro_Poliza,',
'           Email          = :p31_Email,',
'           TlfAsegurado   = :p31_TlfAsegurado,',
'           DirecPostal    = :p31_Direccion_Postal,',
'           DirecFisica    = :p31_Direccion_Fisica',
'     WHERE Id_Catastrofe  = :p31_Id_Catastrofe;',
'     ',
' END IF;',
'END;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(5702725482874352)
);
end;
