,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Guardar'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  cursor cur_emails is',
'   select rv_meaning',
'     from cg_ref_codes',
'    where rv_domain=''EMAIL_RECLAMOS''',
'    order by rv_low_value;',
'    ',
'  l_html_header  clob;',
'  l_html_table_1 clob;',
'  l_html_table_2 clob;',
'  l_html_footer  clob;',
'BEGIN',
'',
' IF :p33_Id_Catastrofe IS NOT NULL AND NVL(:p33_Acepto,''N'') = ''S'' THEN',
'',
'   UPDATE INCIDENTE_CATASTROFE',
'      SET Confirma      = :p33_Acepto,',
'          StsCatastrofe = ''SOL''',
'    WHERE Id_Catastrofe = :p33_Id_Catastrofe;',
'    ',
'      l_html_header := ''<html>',
'                        <head>',
'                        <body>',
'                        <style>',
'                                 .styled-table {',
'                                                text-align: left;',
'                                                border-collapse: collapse;',
'                                                margin: 25px 0;',
'                                                font-size: 0.9em;',
'                                                font-family: sans-serif;',
'                                                min-width: 400px;',
'                                                box-shadow: 0 0 20px rgba(0, 0, 0, 0.15);',
'                                              }',
'                                 .styled-table thead tr',
'                                              {',
'                                                background-color: #009879;',
'                                                color: #ffffff;',
'                                                text-align: left;',
'                                              }',
'                                 .styled-table th, styled-table td {',
'                                                   padding: 12px 15px;',
'                                                 }',
'                                 .styled-table tbody tr {',
'                                                        border-bottom: 1px solid #dddddd;',
'                                                       }',
'',
'                                 .styled-table tbody tr:nth-of-type(even) {',
'                                            background-color: #f3f3f3;',
'                                  }',
'',
'                                 .styled-table tbody tr:last-of-type {',
'                                    border-bottom: 2px solid #009879;',
'                                    }',
'',
'                                 .styled-table tbody tr.active-row {',
'                                    font-weight: bold;',
'                                    color: #009879;',
'                                    }',
'',
'                               </style> ',
'',
'                 <b>Hola, ''||:A_DISPLAYNAME||''</b>,<br>',
'                 <br>',
'                    Su solicitud se ha regisrado!<br>',
'                 <br>',
'                 <b>Detalle del Reporte de Incidente Catastrofe</b><br>',
'                 <br>'';',
'                 ',
'      pr_admin_intermediario.HTML_CATASTROFE_ASEGURADO ( :p33_Id_Catastrofe, l_html_table_1 );',
'      pr_admin_intermediario.HTML_CATASTROFE_INCIDENTE ( :p33_Id_Catastrofe, l_html_table_2 );',
'      ',
'      l_html_footer := '' </body>',
'                         </head>',
'                         </html> '';',
'      for c in cur_emails loop',
'          send_mail_html (''info@singularpr.com '',',
'                          c.rv_meaning,',
unistr('                          ''SINGULAR - Reporte de Incidente Catastrofe. N\00FAmero ''||:p33_Id_Catastrofe,'),
'                           l_html_header',
'                         ||l_html_table_1',
'                         ||l_html_table_2',
'                         ||l_html_footer);',
'       end loop;',
'',
' END IF;',
'',
'END;',
''))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(5713842557874347)
);
