wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(4516053526627653)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Guardar'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P41_Id_Resp_Publica IS NULL THEN',
'    :P41_ID_RESP_PUBLICA := INCIDENTE_RESPON_PUB_SEQ.NEXTVAL;',
'    APEX_UTIL.SET_SESSION_STATE (''P41_ID_RESP_PUBLICA'', :P41_ID_RESP_PUBLICA);',
'',
'   INSERT INTO INCIDENTE_RESP_PUBLICA',
'      ( Id_Resp_Publica, NbreAsegurado, NroPoliza, Email, TlfAsegurado,',
'        DirecPostal, DirecFisica, NbreAfectado, EmailAfectado, TlfAfectado,',
'        UltNroSeguro, EdadAfectado, Medicare, Contacto, DirecPostalAfectado,',
'        DirecFisicaAfectado )',
'   VALUES',
'      ( :p41_Id_Resp_Publica, :p41_NbreAsegurado, :p41_Nro_Poliza, :p41_Email, :p41_TlfAsegurado,',
'        :p41_Direccion_Postal, :p41_Direccion_Fisica, :p41_Nombre_Afectado,:p41_Email_Afectado,:p41_Tlf_Afectado,',
'        :p41_Nss_afectado,:p41_Edad_Afectado,:p41_Medicare,:p41_Contacto,:p41_Direccion_Postal_Afec,',
'        :p41_Direccion_Fisica_Afec);',
'ELSE',
'  UPDATE INCIDENTE_RESP_PUBLICA',
'     SET NbreAsegurado       = :p41_NbreAsegurado,',
'         NroPoliza           = :p41_Nro_Poliza, ',
'         Email               = :p41_Email, ',
'         TlfAsegurado        = :p41_TlfAsegurado,',
'         DirecPostal         = :p41_Direccion_Postal, ',
'         DirecFisica         = :p41_Direccion_Fisica, ',
'         NbreAfectado        = :p41_Nombre_Afectado, ',
'         EmailAfectado       = :p41_Email_Afectado, ',
'         TlfAfectado         = :p41_Tlf_Afectado,',
'         UltNroSeguro        = :p41_Nss_afectado, ',
'         EdadAfectado        = :p41_Edad_Afectado, ',
'         Medicare            = :p41_Medicare, ',
'         Contacto            = :p41_Contacto, ',
'         DirecPostalAfectado = :p41_Direccion_Postal_Afec,',
'         DirecFisicaAfectado = :p41_Direccion_Fisica_Afec',
'   WHERE Id_Resp_Publica  = :p41_Id_Resp_Publica;',
'END IF;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(5759451896568158)
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(4516209994627655)
,p_process_sequence=>10
,p_process_point=>'BEFORE_BOX_BODY'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CargaDatos'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :p41_Id_Resp_Publica IS NOT NULL THEN',
'',
' BEGIN',
'   SELECT NbreAsegurado, NroPoliza, Email, TlfAsegurado,',
'          DirecPostal, DirecFisica, NbreAfectado, EmailAfectado, TlfAfectado,',
'          UltNroSeguro, EdadAfectado, Medicare, Contacto, DirecPostalAfectado,',
'          DirecFisicaAfectado',
'     INTO :p41_NbreAsegurado, :p41_Nro_Poliza, :p41_Email, :p41_TlfAsegurado,',
'          :p41_Direccion_Postal, :p41_Direccion_Fisica, :p41_Nombre_Afectado,:p41_Email_Afectado,:p41_Tlf_Afectado,',
'          :p41_Nss_afectado,:p41_Edad_Afectado,:p41_Medicare,:p41_Contacto,:p41_Direccion_Postal_Afec,',
'          :p41_Direccion_Fisica_Afec',
'     FROM INCIDENTE_RESP_PUBLICA',
'    WHERE Id_Resp_Publica = :p41_Id_Resp_Publica;',
' EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'         :p41_NbreAsegurado   := NULL; :p41_Nro_Poliza            := NULL; :p41_Email                 := NULL;',
'         :p41_TlfAsegurado    := NULL; :p41_Direccion_Postal      := NULL; :p41_Direccion_Fisica      := NULL;',
'         :p41_Nombre_Afectado := NULL; :p41_Email_Afectado        := NULL; :p41_Tlf_Afectado          := NULL;',
'         :p41_Nss_afectado    := NULL; :p41_Edad_Afectado         := NULL; :p41_Medicare              := NULL;',
'         :p41_Contacto        := NULL; :p41_Direccion_Postal_Afec := NULL; :p41_Direccion_Fisica_Afec := NULL;',
' END;',
'',
'END IF;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
