wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(4517166430627664)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Guardar'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P52_Id_Perdida IS NOT NULL THEN',
'   UPDATE INCIDENTE_PERDIDA_PROPIEDAD',
'      SET FechaIncidente   = TO_DATE(:p52_Fecha_Perdida,''MM/DD/YYYY''),',
'          HoraIncidente    = :p52_Hora_Perdida,',
'          TpoIncidente     = :p52_Tpo_Perdida,',
'          ReportadoPolicia = :p52_Reportado,',
'          NroQuerella      = :p52_Nro_Querella,',
'          NbrePolicia      = :p52_Nbre_Policia,',
'          NroPlaca         = :p52_Placa_Policia,',
'          LugarPerdida     = :p52_Lugar_Perdida,',
'          DescPerdida      = :p52_Detalles',
'    WHERE Id_Perdida_Propiedad = :p52_Id_Perdida;',
'END IF;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(4517282449627665)
,p_process_sequence=>10
,p_process_point=>'BEFORE_BOX_BODY'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CargaDatos'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P52_Id_Perdida IS NOT NULL THEN',
'   BEGIN',
'     SELECT FechaIncidente,HoraIncidente,TpoIncidente,ReportadoPolicia,',
'            NroQuerella,NbrePolicia,NroPlaca,LugarPerdida,DescPerdida',
'       INTO :p52_Fecha_Perdida,:p52_Hora_Perdida,:p52_Tpo_Perdida,:p52_Reportado,',
'            :p52_Nro_Querella,:p52_Nbre_Policia,:p52_Placa_Policia,:p52_Lugar_Perdida,:p52_Detalles',
'       FROM INCIDENTE_PERDIDA_PROPIEDAD',
'      WHERE Id_Perdida_Propiedad = :p52_Id_Perdida;',
'   EXCEPTION',
'      WHEN NO_DATA_FOUND THEN',
'           :p52_Fecha_Perdida := NULL;',
'           :p52_Hora_Perdida  := NULL;',
'           :p52_Tpo_Perdida   := NULL;',
'           :p52_Reportado     := NULL;',
'           :p52_Nro_Querella  := NULL;',
'           :p52_Nbre_Policia  := NULL;',
'           :p52_Placa_Policia := NULL;',
'           :p52_Lugar_Perdida := NULL;',
'           :p52_Detalles      := NULL;',
'   END;',
'ELSE',
'   :p52_Fecha_Perdida := NULL;',
'   :p52_Hora_Perdida  := NULL;',
'   :p52_Tpo_Perdida   := NULL;',
'   :p52_Reportado     := NULL;',
'   :p52_Nro_Querella  := NULL;',
'   :p52_Nbre_Policia  := NULL;',
'   :p52_Placa_Policia := NULL;',
'   :p52_Lugar_Perdida := NULL;',
'   :p52_Detalles      := NULL;',
'END IF;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
